          wrong += chunk;
          process.stderr.write(chunk);
        });

        dagger.on("error", (error) => {
          response.statusCode = 500;
          response.end(`couldn't run dagger: ${error.message}`);
        });
        dagger.on("close", (code) => {
          if (code !== 0) {
            response.statusCode = 500;
            response.end(wrong.trim() || `dagger gave up with ${code}`);
            return;
          }
